 "risks": [
  {
   "id": "no_liability_cap",
   "severity": "medium",
   "message": "The lease has no limitation of liability clause, so Northwind's exposure to the Landlord is not capped.",
   "quote": "Neither Party shall be liable for any delay caused by events beyond its reasonable control."
  },
  {
   "id": "no_termination_for_convenience",
   "severity": "medium",
   "message": "The lease does not give Northwind a right to terminate early, so it is likely committed to the full 36-month term (about USD 432,000 in base rent) even if its needs change.",
   "quote": "This Agreement will remain in effect for 36 months from the Effective Date."
  },
  {
   "id": "renewal_notice_unspecified",
   "severity": "medium",
   "message": "The renewal option requires written notice but sets no deadline or method, which creates uncertainty about when Northwind must exercise it to avoid losing the option.",
   "quote": "Tenant shall have one (1) option to renew the Lease for an additional five (5) years by giving written notice."
  },
  {
   "id": "renewal_rent_unspecified",
   "severity": "low",
   "message": "The five-year renewal option does not state the rent for the renewal period, so the Landlord could potentially dispute or reset the rent.",
   "quote": "Tenant shall have one (1) option to renew the Lease for an additional five (5) years by giving written notice."
  },
  {
   "id": "security_deposit",
   "severity": "low",
   "message": "Northwind must post a security deposit of two months' base rent (about USD 24,000). The lease does not state when or how it is returned.",
   "quote": "Tenant shall deliver a security deposit equal to two months' base rent."
  },
  {
   "id": "no_rent_payment_terms",
   "severity": "low",
   "message": "Rent is payable monthly, but the lease sets no due date, late-payment terms or cure period.",
   "quote": "payable in equal monthly installments"
  }
